module filemanager

import crypto.sha256
import json2
import os

// RawPreviewInfo holds the resolved file path, MIME type, and optional generated bytes for raw media/thumbnail streaming.
pub struct RawPreviewInfo {
pub:
	path  string
	mime  string
	size  i64
	mtime i64
	name  string
}

// raw_preview_info resolves a file path and determines its MIME content type for `/api/raw` streaming.
pub fn raw_preview_info(ctx &FmContext, raw_path string) !RawPreviewInfo {
	resolved := resolve_existing(ctx, raw_path, true)!
	st := os.stat(resolved)!
	if os.is_dir(resolved) {
		return error('IS_DIRECTORY: Cannot stream a directory as a raw file.')
	}
	ext := ext_of(os.base(resolved), false)
	mime := match ext {
		'png' { 'image/png' }
		'jpg', 'jpeg' { 'image/jpeg' }
		'gif' { 'image/gif' }
		'webp' { 'image/webp' }
		'svg' { 'image/svg+xml' }
		'bmp' { 'image/bmp' }
		'ico' { 'image/x-icon' }
		'avif' { 'image/avif' }
		'heic' { 'image/heic' }
		'heif' { 'image/heif' }
		'tif', 'tiff' { 'image/tiff' }
		'mp4', 'm4v' { 'video/mp4' }
		'webm' { 'video/webm' }
		'mov' { 'video/quicktime' }
		'mkv' { 'video/x-matroska' }
		'avi' { 'video/x-msvideo' }
		'ogv' { 'video/ogg' }
		'mp3' { 'audio/mpeg' }
		'wav' { 'audio/wav' }
		'ogg', 'opus' { 'audio/ogg' }
		'flac' { 'audio/flac' }
		'm4a' { 'audio/mp4' }
		'aac' { 'audio/aac' }
		'pdf' { 'application/pdf' }
		'txt', 'log', 'md', 'csv', 'tsv' { 'text/plain; charset=utf-8' }
		'json' { 'application/json; charset=utf-8' }
		'html', 'htm' { 'text/html; charset=utf-8' }
		'css' { 'text/css; charset=utf-8' }
		'js', 'mjs' { 'text/javascript; charset=utf-8' }
		else { 'application/octet-stream' }
	}
	return RawPreviewInfo{
		path:  resolved
		mime:  mime
		size:  i64(st.size)
		mtime: st.mtime * 1000
		name:  os.base(resolved)
	}
}

// generate_thumbnail generates or caches a resized image thumbnail up to `max_size` pixels.
pub fn generate_thumbnail(ctx &FmContext, raw_path string, max_size int) ?RawPreviewInfo {
	resolved := resolve_existing(ctx, raw_path, true) or { return none }
	if os.is_dir(resolved) {
		return none
	}
	st := os.stat(resolved) or { return none }
	clamped := if max_size < 64 {
		64
	} else if max_size > 1024 {
		1024
	} else {
		max_size
	}
	ext := ext_of(os.base(resolved), false)

	// Direct browser-native images under 8 MB need no transcoding
	if ext in ['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg', 'bmp', 'ico', 'avif']
		&& st.size < 8 * 1024 * 1024 {
		return raw_preview_info(ctx, resolved) or { return none }
	}

	thumb_dir := os.join_path(ctx.data_dir, 'thumbs')
	os.mkdir_all(thumb_dir) or { return none }
	cache_key := sha256.hexhash('${resolved}:${st.size}:${st.mtime}:${clamped}')[..24]
	out_png := os.join_path(thumb_dir, '${cache_key}.png')

	if !os.exists(out_png) {
		$if macos {
			ql_res := os.execute('qlmanage -t -s ${clamped} -o ${os.quoted_path(thumb_dir)} ${os.quoted_path(resolved)} >/dev/null 2>&1')
			produced := os.join_path(thumb_dir, '${os.base(resolved)}.png')
			if ql_res.exit_code == 0 && os.exists(produced) {
				os.mv(produced, out_png) or {}
			} else if ext in ['heic', 'heif', 'tif', 'tiff', 'png', 'jpg', 'jpeg', 'bmp'] {
				os.execute('sips -s format png -Z ${clamped} ${os.quoted_path(resolved)} --out ${os.quoted_path(out_png)} >/dev/null 2>&1')
			}
		} $else {
			if ext in ['mp4', 'webm', 'mov', 'mkv', 'avi', 'm4v'] {
				os.execute('ffmpeg -y -ss 00:00:01 -i ${os.quoted_path(resolved)} -frames:v 1 -vf "scale=${clamped}:-1" ${os.quoted_path(out_png)} >/dev/null 2>&1')
			}
		}
	}

	if os.exists(out_png) {
		tst := os.stat(out_png) or { return none }
		if tst.size > 0 {
			return RawPreviewInfo{
				path:  out_png
				mime:  'image/png'
				size:  i64(tst.size)
				mtime: tst.mtime * 1000
				name:  os.base(out_png)
			}
		}
	}

	// Fallback to raw file if image
	if ext in ['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg', 'bmp', 'ico'] {
		return raw_preview_info(ctx, resolved) or { return none }
	}
	return none
}

// handle_native_quicklook invokes the OS native previewer (e.g. macOS `qlmanage -p`) on the requested path.
pub fn handle_native_quicklook(ctx &FmContext, b map[string]json2.Any) !string {
	raw_path := map_str(b, 'path', '')
	resolved := resolve_existing(ctx, raw_path, false)!
	$if macos {
		spawn fn [resolved] () {
			os.execute('qlmanage -p ${os.quoted_path(resolved)} >/dev/null 2>&1')
		}()
		return '{"launched":true,"platform":"darwin"}'
	} $else $if linux {
		open_url_or_path_in_os(resolved)
		return '{"launched":true,"platform":"linux"}'
	} $else {
		open_url_or_path_in_os(resolved)
		return '{"launched":true,"platform":"win32"}'
	}
}

fn format_hex_dump(buf []u8) string {
	mut lines := []string{}
	limit := if buf.len > 512 { 512 } else { buf.len }
	for offset := 0; offset < limit; offset += 16 {
		end := if offset + 16 < limit { offset + 16 } else { limit }
		slice := buf[offset..end]
		mut hex_parts := []string{}
		mut ascii_chars := []u8{}
		for b in slice {
			hex_parts << '${b:02x}'
			ascii_chars << if b >= 32 && b <= 126 { b } else { u8(`.`) }
		}
		hex_col := '${hex_parts.join(' '):-47s}'
		lines << '${offset:04x}  ${hex_col}  ${ascii_chars.bytestr()}'
	}
	return lines.join('\n')
}

fn looks_binary_bytes(buf []u8) bool {
	if buf.len == 0 {
		return false
	}
	sample_len := if buf.len > 4096 { 4096 } else { buf.len }
	mut suspicious := 0
	for i in 0 .. sample_len {
		b := buf[i]
		if b == 0 {
			return true
		}
		if b < 7 || (b > 14 && b < 32 && b != 27) {
			suspicious++
		}
	}
	return f64(suspicious) / f64(sample_len) > 0.15
}

pub fn read_file_head(path string, max_len int) []u8 {
	if max_len <= 0 {
		return []u8{}
	}
	mut f := os.open(path) or { return []u8{} }
	defer {
		f.close()
	}
	mut buf := []u8{len: max_len}
	n := f.read_bytes_into(0, mut buf) or { return []u8{} }
	if n <= 0 {
		return []u8{}
	}
	return buf[..n].clone()
}

// handle_preview_item returns a structured preview payload (text, code, markdown, hex, archive list, or media URL) for a file.
pub fn handle_preview_item(ctx &FmContext, b map[string]json2.Any) !string {
	raw_path := map_str(b, 'path', '')
	req_max := map_int(b, 'maxBytes', 262144)
	max_bytes := if req_max > 0 {
		if req_max < 4 * 1024 * 1024 { req_max } else { 4 * 1024 * 1024 }
	} else {
		262144
	}
	resolved := resolve_existing(ctx, raw_path, false)!
	real_target := os.real_path(resolved)
	if !inside_roots(ctx, real_target) {
		return error('OUTSIDE_ROOTS: Symlink target is outside allowed roots.')
	}
	name := if os.base(resolved) != '' { os.base(resolved) } else { resolved }
	entry := build_entry(resolved, name) or { return error('NOT_FOUND: Cannot stat ${raw_path}') }
	perms := format_perm_str(entry.mode, entry.is_dir, entry.is_symlink)
	octal := '0${(entry.mode & 0o777):03o}'
	can_ql := $if macos { true } $else { false }

	if entry.is_dir {
		mut child_count := 0
		if names := os.ls(resolved) {
			child_count = names.len
		}
		return '{"preview":{"type":"none","size":0},"entry":${entry_to_json(entry)},"previewKind":"folder","permissions":${json_str(perms)},"octalPermissions":${json_str(octal)},"childCount":${child_count},"canNativeQuickLook":${json_bool(can_ql)}}'
	}

	if entry.kind in ['image', 'video', 'audio', 'pdf'] {
		ptype := if entry.kind == 'pdf' { 'thumb' } else { entry.kind }
		return '{"preview":{"type":${json_str(ptype)},"size":${entry.size}},"entry":${entry_to_json(entry)},"previewKind":${json_str(entry.kind)},"permissions":${json_str(perms)},"octalPermissions":${json_str(octal)},"rawKind":${json_str(entry.kind)},"canNativeQuickLook":${json_bool(can_ql)}}'
	}

	if entry.ext == 'zip' {
		mut zip_map := map[string]json2.Any{}
		zip_map['path'] = json2.Any(resolved)
		if zinfo := handle_zip_list(ctx, zip_map) {
			if zinfo.starts_with('{') && zinfo.ends_with('}') {
				inner := zinfo[1..zinfo.len - 1]
				return '{"preview":{"type":"binary","size":${entry.size}},"entry":${entry_to_json(entry)},"previewKind":"archive","permissions":${json_str(perms)},"octalPermissions":${json_str(octal)},"canNativeQuickLook":${json_bool(can_ql)},${inner}}'
			}
		}
	}

	if entry.kind == 'database' {
		py_sql := '
import sys, json, sqlite3, urllib.parse
p = urllib.parse.quote(sys.argv[1], safe="/:")
conn = sqlite3.connect(f"file:{p}?mode=ro", uri=True)
cur = conn.cursor()
cur.execute("PRAGMA trusted_schema = OFF")
cur.execute("SELECT name, type FROM sqlite_master WHERE type IN (\'table\', \'view\') AND name NOT LIKE \'sqlite_%\' ORDER BY type, name LIMIT 64")
rows = cur.fetchall()
tables = []
total_rows = 0
for name, ttype in rows:
    safe_ident = str(name).replace(\'"\', \'""\')
    cols = []
    try:
        cur.execute(f\'PRAGMA table_info("{safe_ident}")\')
        for c in cur.fetchall():
            cols.append({"name": str(c[1]), "type": str(c[2] or "ANY"), "pk": bool(c[5])})
    except Exception:
        pass
    rc = 0
    if ttype == "table":
        try:
            cur.execute(f\'SELECT COUNT(*) FROM "{safe_ident}"\')
            rc = int(cur.fetchone()[0])
            total_rows += rc
        except Exception:
            pass
    tables.append({"name": name, "type": ttype, "rowCount": rc, "columns": cols})
conn.close()
print(json.dumps({"tables": tables, "totalRows": total_rows}))
'
		res := os.execute('python3 -c ${os.quoted_path(py_sql)} ${os.quoted_path(resolved)} 2>/dev/null')
		if res.exit_code == 0 {
			out := res.output.trim_space()
			if out.starts_with('{') && out.ends_with('}') {
				inner := out[1..out.len - 1]
				return '{"preview":{"type":"binary","size":${entry.size}},"entry":${entry_to_json(entry)},"previewKind":"database","permissions":${json_str(perms)},"octalPermissions":${json_str(octal)},"canNativeQuickLook":${json_bool(can_ql)},${inner}}'
			}
		}
	}

	raw_bytes := read_file_head(resolved, max_bytes + 1)
	truncated := raw_bytes.len > max_bytes || entry.size > i64(max_bytes)
	slice := if raw_bytes.len > max_bytes { raw_bytes[..max_bytes] } else { raw_bytes }

	if looks_binary_bytes(slice) {
		hex_str := format_hex_dump(slice)
		return '{"preview":{"type":"binary","size":${entry.size}},"entry":${entry_to_json(entry)},"previewKind":"binary","permissions":${json_str(perms)},"octalPermissions":${json_str(octal)},"hexPreview":${json_str(hex_str)},"truncated":${json_bool(entry.size > 512)},"canNativeQuickLook":${json_bool(can_ql)}}'
	}

	content := slice.bytestr()
	line_count := if content.len == 0 { 0 } else { content.count('\n') + 1 }
	pkind := if entry.kind in ['code', 'markdown', 'data'] { entry.kind } else { 'text' }
	return '{"preview":{"type":"text","text":${json_str(content)},"truncated":${json_bool(truncated)},"size":${entry.size}},"entry":${entry_to_json(entry)},"previewKind":${json_str(pkind)},"permissions":${json_str(perms)},"octalPermissions":${json_str(octal)},"content":${json_str(content)},"truncated":${json_bool(truncated)},"lineCount":${line_count},"encoding":"utf-8","canNativeQuickLook":${json_bool(can_ql)}}'
}

// handle_save_text writes updated text content back to an existing file on disk.
pub fn handle_save_text(ctx &FmContext, b map[string]json2.Any) !string {
	raw_path := map_str(b, 'path', '')
	content := map_str(b, 'content', '')
	resolved := resolve_existing(ctx, raw_path, true)!
	check_not_protected(ctx, resolved, 'modify')!
	if os.is_dir(resolved) {
		return error('IS_DIRECTORY: Cannot write text content to a directory.')
	}
	os.write_file(resolved, content)!
	entry := build_entry(resolved, os.base(resolved)) or {
		return error('NOT_FOUND: Saved file could not be read.')
	}
	return '{"entry":${entry_to_json(entry)}}'
}
